30	/** Awaits a call that must reject and returns the thrown error for assertions. */
31	async function rejection(call: Promise<unknown>): Promise<unknown> {
32	  try {
33	    await call;
34	  } catch (error) {
35	    return error;
36	  }
37	  throw new Error("Expected the call to reject, but it resolved");
38	}
