40	async function expectApiError(
41	  call: Promise<unknown>,
42	  expected: { status: number; code: string; message?: string },
43	) {
44	  const error = await rejection(call);
45	  expect(error).toBeInstanceOf(PaymentsApiError);
46	  const apiError = error as PaymentsApiError;
47	  expect(apiError.status).toBe(expected.status);
48	  expect(apiError.code).toBe(expected.code);
49	  if (expected.message !== undefined) {
50	    expect(apiError.message).toBe(expected.message);
51	  }
52	}
